import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    if m == 0:
        print(0)
        return

    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        edges.append((w, u - 1, v - 1))

    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    total_weight = 0
    edges_used = 0

    for w, u, v in edges:
        if union(u, v):
            total_weight += w
            edges_used += 1
            if edges_used == n - 1:
                break

    print(total_weight)

if __name__ == "__main__":
    main()
